import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const T=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"设计与实现","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/operator_function_design"},{"text":"多分支策略","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/multi_branch_strategy"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/multi_branch_strategy.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/multi_branch_strategy.md","outlineHeaders":[{"level":2,"title":"为什么需要多分支","slug":"为什么需要多分支","link":"#为什么需要多分支"},{"level":2,"title":"使用TilingKey选择分支","slug":"使用TilingKey选择分支","link":"#使用TilingKey选择分支"},{"level":3,"title":"Host侧设置TilingKey","slug":"Host侧设置TilingKey","link":"#Host侧设置TilingKey"},{"level":3,"title":"核函数（Kernel）侧声明分支","slug":"核函数（Kernel）侧声明分支","link":"#核函数（Kernel）侧声明分支"},{"level":3,"title":"为特定分支使用不同TilingData","slug":"为特定分支使用不同TilingData","link":"#为特定分支使用不同TilingData"},{"level":3,"title":"只编译指定TilingKey","slug":"只编译指定TilingKey","link":"#只编译指定TilingKey"},{"level":2,"title":"使用核函数（Kernel）模板组织分支","slug":"使用核函数（Kernel）模板组织分支","link":"#使用核函数（Kernel）模板组织分支"},{"level":3,"title":"为什么需要核函数（Kernel）模板","slug":"为什么需要核函数（Kernel）模板","link":"#为什么需要核函数（Kernel）模板"},{"level":3,"title":"步骤一：定义模板参数","slug":"步骤一：定义模板参数","link":"#步骤一：定义模板参数"},{"level":3,"title":"步骤二：Host侧配置","slug":"步骤二：Host侧配置","link":"#步骤二：Host侧配置"},{"level":3,"title":"步骤三：核函数（Kernel）侧实现","slug":"步骤三：核函数（Kernel）侧实现","link":"#步骤三：核函数（Kernel）侧实现"},{"level":3,"title":"编译加速","slug":"编译加速","link":"#编译加速"},{"level":2,"title":"如何选择","slug":"如何选择","link":"#如何选择"},{"level":2,"title":"相关文档","slug":"相关文档","link":"#相关文档"}],"lastUpdated":1788139350000}'),c={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/multi_branch_strategy.md"};function e(t,s,o,i,d,_){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>多分支策略</h1><p>本文属于扩展内容，介绍同一个算子需要根据dtype、shape或属性执行不同计算流程时，如何使用TilingKey或核函数（Kernel）模板组织多个核函数（Kernel）分支。TilingKey使用数字标识分支，适合分支数量较少、含义稳定的场景；核函数（Kernel）模板使用具名参数描述分支，适合由多个维度共同决定分支的场景。</p><p>本文分别说明两种方式的使用原因、Host与核函数（Kernel）侧的对应关系以及接入步骤。</p><h2 id="为什么需要多分支">为什么需要多分支<a class="header-anchor" href="#为什么需要多分支">​</a></h2><p>普通的运行时分支会将所有处理逻辑保留在同一个核函数（Kernel）中：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">condition</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">ProcessA</span><span class="p">();</span>
<span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">ProcessB</span><span class="p">();</span>
<span class="p">}</span>
</code></pre></div><p>单次执行虽然只会进入其中一个分支，但两个分支的代码都属于同一个核函数（Kernel）。分支代码较大时，会增加指令缓存压力和Scalar侧的控制开销。</p><p>使用TilingKey后，可以将分支条件变为编译期常量：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">TILING_KEY_IS</span><span class="p">(</span><span class="mi">1</span><span class="p">))</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">ProcessA</span><span class="p">();</span>
<span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">TILING_KEY_IS</span><span class="p">(</span><span class="mi">2</span><span class="p">))</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">ProcessB</span><span class="p">();</span>
<span class="p">}</span>
</code></pre></div><p>编译时框架会自动识别TilingKey并编译多个核函数（Kernel）入口函数，将条件判断进行<strong>常量折叠</strong>，消除运行时的分支判断开销。</p><p>增加分支前，还需要判断差异是否确实需要独立核函数（Kernel）实现：</p><table><thead><tr><th>分支维度</th><th>Host侧判断依据</th><th>典型差异</th></tr></thead><tbody><tr><td>dtype</td><td><code>context-&gt;GetInputDesc()</code>、<code>context-&gt;GetOutputDesc()</code></td><td>计算类型、搬运粒度、精度策略</td></tr><tr><td>shape</td><td><code>context-&gt;GetInputShape()</code></td><td>小shape直算、大shape分块、尾块处理</td></tr><tr><td>属性</td><td><code>context-&gt;GetAttrs()</code></td><td>算法模式、维度、开关</td></tr><tr><td>format</td><td>输入输出描述</td><td>数据组织和搬运方式</td></tr></tbody></table><p>如果不同场景只影响Tile大小、Block数量等运行参数，而核函数（Kernel）计算流程不变，只需要在TilingData中传递不同参数，不必增加核函数（Kernel）分支。只有计算流程、数据类型实例或代码体积确实不同，才需要使用TilingKey或核函数（Kernel）模板。</p><h2 id="使用TilingKey选择分支">使用TilingKey选择分支<a class="header-anchor" href="#使用TilingKey选择分支">​</a></h2><p>TilingKey使用非负整数标识核函数（Kernel）分支。Host侧通过<code>SetTilingKey</code>选择本次执行的key，核函数（Kernel）侧通过<code>TILING_KEY_IS(key)</code>声明与该key对应的分支。</p><h3 id="Host侧设置TilingKey">Host侧设置TilingKey<a class="header-anchor" href="#Host侧设置TilingKey">​</a></h3><p>TilingKey只负责选择核函数（Kernel）计算分支，并不要求每个分支使用不同的TilingData。多个分支需要的运行参数结构相同时，可以共用一个TilingData。下面根据输入数据量选择不同分支，并通过同一个<code>TilingData</code>传递参数：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">namespace</span><span class="w"> </span><span class="nn">optiling</span><span class="w"> </span><span class="p">{</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">SHAPE_THRESHOLD</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1024</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">NUM_BLOCKS</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>

<span class="k">static</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">graphStatus</span><span class="w"> </span><span class="nf">TilingFunc</span><span class="p">(</span><span class="n">gert</span><span class="o">::</span><span class="n">TilingContext</span><span class="o">*</span><span class="w"> </span><span class="n">context</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">totalLength</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetInputTensor</span><span class="p">(</span><span class="mi">0</span><span class="p">)</span><span class="o">-&gt;</span><span class="n">GetShapeSize</span><span class="p">();</span>
<span class="w">    </span><span class="n">TilingData</span><span class="o">*</span><span class="w"> </span><span class="n">tiling</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetTilingData</span><span class="o">&lt;</span><span class="n">TilingData</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">tiling</span><span class="o">-&gt;</span><span class="n">totalLength</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">totalLength</span><span class="p">;</span>

<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">totalLength</span><span class="w"> </span><span class="o">&lt;=</span><span class="w"> </span><span class="n">SHAPE_THRESHOLD</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">context</span><span class="o">-&gt;</span><span class="n">SetTilingKey</span><span class="p">(</span><span class="mi">1</span><span class="p">);</span>
<span class="w">        </span><span class="n">tiling</span><span class="o">-&gt;</span><span class="n">tileNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">context</span><span class="o">-&gt;</span><span class="n">SetTilingKey</span><span class="p">(</span><span class="mi">2</span><span class="p">);</span>
<span class="w">        </span><span class="n">tiling</span><span class="o">-&gt;</span><span class="n">tileNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">NUM_BLOCKS</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>

<span class="w">    </span><span class="n">context</span><span class="o">-&gt;</span><span class="n">SetSimdNumBlocks</span><span class="p">(</span><span class="n">NUM_BLOCKS</span><span class="p">);</span>
<span class="w">    </span><span class="kt">size_t</span><span class="o">*</span><span class="w"> </span><span class="n">currentWorkspace</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetWorkspaceSizes</span><span class="p">(</span><span class="mi">1</span><span class="p">);</span>
<span class="w">    </span><span class="n">currentWorkspace</span><span class="p">[</span><span class="mi">0</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="w">    </span><span class="k">return</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">GRAPH_SUCCESS</span><span class="p">;</span>
<span class="p">}</span>
<span class="p">}</span><span class="w"> </span><span class="c1">// namespace optiling</span>
</code></pre></div><h3 id="核函数（Kernel）侧声明分支">核函数（Kernel）侧声明分支<a class="header-anchor" href="#核函数（Kernel）侧声明分支">​</a></h3><p>在核函数（Kernel）中通过<code>TILING_KEY_IS</code>选择计算分支：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">extern</span><span class="w"> </span><span class="s">&quot;C&quot;</span><span class="w"> </span><span class="n">__global__</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">my_op</span><span class="p">(</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">workspace</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">tiling</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">REGISTER_TILING_DEFAULT</span><span class="p">(</span><span class="n">optiling</span><span class="o">::</span><span class="n">TilingData</span><span class="p">);</span>
<span class="w">    </span><span class="n">GET_TILING_DATA</span><span class="p">(</span><span class="n">tilingData</span><span class="p">,</span><span class="w"> </span><span class="n">tiling</span><span class="p">);</span>

<span class="w">    </span><span class="n">KernelMyOp</span><span class="w"> </span><span class="n">op</span><span class="p">;</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">Init</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">tilingData</span><span class="p">.</span><span class="n">totalLength</span><span class="p">,</span><span class="w"> </span><span class="n">tilingData</span><span class="p">.</span><span class="n">tileNum</span><span class="p">);</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">TILING_KEY_IS</span><span class="p">(</span><span class="mi">1</span><span class="p">))</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">op</span><span class="p">.</span><span class="n">ProcessSmall</span><span class="p">();</span>
<span class="w">    </span><span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">TILING_KEY_IS</span><span class="p">(</span><span class="mi">2</span><span class="p">))</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">op</span><span class="p">.</span><span class="n">ProcessLarge</span><span class="p">();</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><h3 id="为特定分支使用不同TilingData">为特定分支使用不同TilingData<a class="header-anchor" href="#为特定分支使用不同TilingData">​</a></h3><p>只有某个分支的字段集合或布局与默认结构体不同时，才需要为该TilingKey注册单独的TilingData类型。例如，key 1使用默认的<code>TilingData</code>，key 2使用<code>TilingData1</code>：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">REGISTER_TILING_DEFAULT</span><span class="p">(</span><span class="n">optiling</span><span class="o">::</span><span class="n">TilingData</span><span class="p">);</span>
<span class="n">REGISTER_TILING_FOR_TILINGKEY</span><span class="p">(</span><span class="s">&quot;(TILING_KEY_VAR == 2)&quot;</span><span class="p">,</span><span class="w"> </span><span class="n">optiling</span><span class="o">::</span><span class="n">TilingData1</span><span class="p">);</span>

<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">TILING_KEY_IS</span><span class="p">(</span><span class="mi">1</span><span class="p">))</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">GET_TILING_DATA</span><span class="p">(</span><span class="n">tilingData</span><span class="p">,</span><span class="w"> </span><span class="n">tiling</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 使用默认的TilingData</span>
<span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">TILING_KEY_IS</span><span class="p">(</span><span class="mi">2</span><span class="p">))</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">GET_TILING_DATA_WITH_STRUCT</span><span class="p">(</span><span class="n">optiling</span><span class="o">::</span><span class="n">TilingData1</span><span class="p">,</span><span class="w"> </span><span class="n">tilingData</span><span class="p">,</span><span class="w"> </span><span class="n">tiling</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 使用key 2对应的TilingData1</span>
<span class="p">}</span>
</code></pre></div><p>使用<a href="../../../../../api/SIMD-API/basic_api/Kernel-Tiling/REGISTER_TILING_FOR_TILINGKEY.html">REGISTER_TILING_FOR_TILINGKEY</a>时，必须同时通过<a href="../../../../../api/SIMD-API/basic_api/Kernel-Tiling/REGISTER_TILING_DEFAULT.html">REGISTER_TILING_DEFAULT</a>注册默认结构体。Host侧也需要在key 2分支中调用<code>GetTilingData&lt;TilingData1&gt;()</code>写入数据，保证两侧类型和字段布局一致。</p><h3 id="只编译指定TilingKey">只编译指定TilingKey<a id="compile-selected-tiling-keys"></a><a class="header-anchor" href="#只编译指定TilingKey">​</a></h3><p>开发调试时，可以通过<code>--tiling_key</code>仅编译指定key，加速编译过程：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">ascendc_kernels</span><span class="w"> </span><span class="s">MyOp</span>
<span class="w">    </span><span class="s">COMPUTE_UNIT</span><span class="w"> </span><span class="s">Ascendxxxyy</span>
<span class="w">    </span><span class="s">OPTIONS</span><span class="w"> </span><span class="s">--tiling_key=1</span><span class="p">)</span>
</code></pre></div><p>按系列配置时可将<code>COMPUTE_UNIT</code>替换为<code>SOC_SERIES</code>，例如<code>SOC_SERIES Ascendxxx</code>。同一次调用中两者不能同时使用。</p><p>关于编译选项的完整说明见<a href="../compilation_and_deployment/basic_process.html#custom-compile-options">编译与部署基本流程</a>。</p><h2 id="使用核函数（Kernel）模板组织分支">使用核函数（Kernel）模板组织分支<span id="使用kernel模板组织分支"></span><a class="header-anchor" href="#使用核函数（Kernel）模板组织分支">​</a></h2><h3 id="为什么需要核函数（Kernel）模板">为什么需要核函数（Kernel）模板<a class="header-anchor" href="#为什么需要核函数（Kernel）模板">​</a></h3><p>TilingKey使用数字标识分支。分支数量较多或同时受dtype、Tile数量、布尔开关等多个条件影响时，仅通过数字难以直接看出每个分支的含义，Host与核函数（Kernel）侧的映射关系也更难维护。</p><p>核函数（Kernel）模板将这些分支维度声明为具名模板参数，例如<code>D_T_X</code>、<code>TILE_NUM</code>和<code>IS_SPLIT</code>。模板参数组合由头文件统一约束，Host侧通过<code>ASCENDC_TPL_SEL_PARAM</code>选择组合，核函数（Kernel）入口直接接收对应的编译期类型和常量。</p><h3 id="步骤一：定义模板参数">步骤一：定义模板参数<a class="header-anchor" href="#步骤一：定义模板参数">​</a></h3><p>通过<code>ASCENDC_TPL_ARGS_DECL</code>声明模板参数，通过<code>ASCENDC_TPL_SEL</code>声明允许生成的参数组合。</p><p>核函数（Kernel）模板编程常用宏如下，具体API参考见<a href="../../../../../api/Utils-API/Tiling_template_programming/template_params_definition.html">模板参数定义</a>：</p><table><thead><tr><th>宏类别</th><th>宏名称</th><th>作用</th></tr></thead><tbody><tr><td>声明入口</td><td><code>ASCENDC_TPL_ARGS_DECL</code></td><td>定义模板参数列表及顺序。</td></tr><tr><td>数据类型参数</td><td><code>ASCENDC_TPL_DATATYPE_DECL</code></td><td>声明数据类型模板参数及可选值。</td></tr><tr><td>整数参数</td><td><code>ASCENDC_TPL_UINT_DECL</code></td><td>声明无符号整数模板参数、编码位宽和取值范围。</td></tr><tr><td>布尔参数</td><td><code>ASCENDC_TPL_BOOL_DECL</code></td><td>声明布尔模板参数及可选值。</td></tr><tr><td>组合入口</td><td><code>ASCENDC_TPL_SEL</code></td><td>定义允许生成的模板参数组合列表。</td></tr><tr><td>单组组合</td><td><code>ASCENDC_TPL_ARGS_SEL</code></td><td>定义一组模板参数组合。</td></tr><tr><td>组合约束</td><td><code>ASCENDC_TPL_DATATYPE_SEL</code>、<code>ASCENDC_TPL_UINT_SEL</code>、<code>ASCENDC_TPL_BOOL_SEL</code></td><td>约束一组组合中各参数的取值。</td></tr><tr><td>TilingData结构体</td><td><code>ASCENDC_TPL_TILING_STRUCT_SEL</code></td><td>为当前<code>ASCENDC_TPL_ARGS_SEL</code>模板参数组合指定TilingData结构体，不作为核函数（Kernel）模板参数传入。</td></tr></tbody></table><p>在算子工程的op_kernel目录下，新增头文件定义模板参数和模板参数组合。本示例中头文件命名为<code>tiling_key_add_custom_template.h</code>。下面以dtype、Tile数量和切分开关为例：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#ifndef TILING_KEY_ADD_CUSTOM_TEMPLATE_H</span>
<span class="cp">#define TILING_KEY_ADD_CUSTOM_TEMPLATE_H</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;ascendc/host_api/tiling/template_argument.h&quot;</span>

<span class="n">ASCENDC_TPL_ARGS_DECL</span><span class="p">(</span>
<span class="w">    </span><span class="n">AddCustomTemplate</span><span class="p">,</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_DATATYPE_DECL</span><span class="p">(</span><span class="n">D_T_X</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT16</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_DATATYPE_DECL</span><span class="p">(</span><span class="n">D_T_Y</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT16</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_DATATYPE_DECL</span><span class="p">(</span><span class="n">D_T_Z</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT16</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_UINT_DECL</span><span class="p">(</span><span class="n">TILE_NUM</span><span class="p">,</span><span class="w"> </span><span class="n">ASCENDC_TPL_8_BW</span><span class="p">,</span>
<span class="w">                          </span><span class="n">ASCENDC_TPL_UI_LIST</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_BOOL_DECL</span><span class="p">(</span><span class="n">IS_SPLIT</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">),</span>
<span class="p">);</span>

<span class="n">ASCENDC_TPL_SEL</span><span class="p">(</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_ARGS_SEL</span><span class="p">(</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_DATATYPE_SEL</span><span class="p">(</span><span class="n">D_T_X</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT16</span><span class="p">),</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_DATATYPE_SEL</span><span class="p">(</span><span class="n">D_T_Y</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT16</span><span class="p">),</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_DATATYPE_SEL</span><span class="p">(</span><span class="n">D_T_Z</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT16</span><span class="p">),</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_UINT_SEL</span><span class="p">(</span><span class="n">TILE_NUM</span><span class="p">,</span><span class="w"> </span><span class="n">ASCENDC_TPL_UI_LIST</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">),</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_BOOL_SEL</span><span class="p">(</span><span class="n">IS_SPLIT</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">),</span>
<span class="w">    </span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_ARGS_SEL</span><span class="p">(</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_DATATYPE_SEL</span><span class="p">(</span><span class="n">D_T_X</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT</span><span class="p">),</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_DATATYPE_SEL</span><span class="p">(</span><span class="n">D_T_Y</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT</span><span class="p">),</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_DATATYPE_SEL</span><span class="p">(</span><span class="n">D_T_Z</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT</span><span class="p">),</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_UINT_SEL</span><span class="p">(</span><span class="n">TILE_NUM</span><span class="p">,</span><span class="w"> </span><span class="n">ASCENDC_TPL_UI_LIST</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">),</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_BOOL_SEL</span><span class="p">(</span><span class="n">IS_SPLIT</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">),</span>
<span class="w">    </span><span class="p">),</span>
<span class="p">);</span>
<span class="cp">#endif </span><span class="c1">// TILING_KEY_ADD_CUSTOM_TEMPLATE_H</span>
</code></pre></div><p><code>ASCENDC_TPL_ARGS_DECL</code>声明模板参数及每个参数的取值集合，<code>ASCENDC_TPL_SEL</code>声明模板参数组合，<code>ASCENDC_TPL_ARGS_SEL</code>都描述一组可实例化的核函数（Kernel）模板参数组合。<code>ASCENDC_TPL_ARGS_DECL</code>中各模板参数的排列顺序，需要与<code>ASCENDC_TPL_ARGS_SEL</code>、Host侧<code>ASCENDC_TPL_SEL_PARAM</code>的传参顺序以及核函数（Kernel）的模板参数顺序保持一致。</p><h3 id="步骤二：Host侧配置">步骤二：Host侧配置<a class="header-anchor" href="#步骤二：Host侧配置">​</a></h3><p>Host侧从输入描述和shape得到模板参数的具体值，然后按声明顺序传给<code>ASCENDC_TPL_SEL_PARAM</code>。该接口根据传入的模板参数值选择组合自动生成并配置TilingKey。</p><table><thead><tr><th>声明参数</th><th>Host侧传入值</th><th>核函数（Kernel）模板参数</th></tr></thead><tbody><tr><td><code>D_T_X</code></td><td><code>dtypeX</code></td><td><code>typename D_T_X</code></td></tr><tr><td><code>D_T_Y</code></td><td><code>dtypeY</code></td><td><code>typename D_T_Y</code></td></tr><tr><td><code>D_T_Z</code></td><td><code>dtypeZ</code></td><td><code>typename D_T_Z</code></td></tr><tr><td><code>TILE_NUM</code></td><td><code>tileNum</code></td><td><code>int TILE_NUM</code></td></tr><tr><td><code>IS_SPLIT</code></td><td><code>isSplit</code></td><td><code>int IS_SPLIT</code></td></tr></tbody></table><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;register/op_def_registry.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;../op_kernel/add_custom_template_tiling.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;../op_kernel/tiling_key_add_custom_template.h&quot;</span>

<span class="k">static</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">graphStatus</span><span class="w"> </span><span class="nf">TilingFunc</span><span class="p">(</span><span class="n">gert</span><span class="o">::</span><span class="n">TilingContext</span><span class="o">*</span><span class="w"> </span><span class="n">context</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">totalLength</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetInputShape</span><span class="p">(</span><span class="mi">0</span><span class="p">)</span><span class="o">-&gt;</span><span class="n">GetOriginShape</span><span class="p">().</span><span class="n">GetShapeSize</span><span class="p">();</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dtypeX</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetInputDesc</span><span class="p">(</span><span class="mi">0</span><span class="p">)</span><span class="o">-&gt;</span><span class="n">GetDataType</span><span class="p">());</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dtypeY</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetInputDesc</span><span class="p">(</span><span class="mi">1</span><span class="p">)</span><span class="o">-&gt;</span><span class="n">GetDataType</span><span class="p">());</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dtypeZ</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetOutputDesc</span><span class="p">(</span><span class="mi">0</span><span class="p">)</span><span class="o">-&gt;</span><span class="n">GetDataType</span><span class="p">());</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">numBlocks</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">totalLength</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="mi">2048</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="mi">1</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">tileNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">totalLength</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="mi">2048</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="mi">1</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">isSplit</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">totalLength</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="mi">2048</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="mi">0</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>

<span class="w">    </span><span class="n">TilingDataTemplate</span><span class="o">*</span><span class="w"> </span><span class="n">tiling</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetTilingData</span><span class="o">&lt;</span><span class="n">TilingDataTemplate</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">tiling</span><span class="o">-&gt;</span><span class="n">totalLength</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">totalLength</span><span class="p">;</span>
<span class="w">    </span><span class="n">context</span><span class="o">-&gt;</span><span class="n">SetSimdNumBlocks</span><span class="p">(</span><span class="n">numBlocks</span><span class="p">);</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_SEL_PARAM</span><span class="p">(</span><span class="n">context</span><span class="p">,</span><span class="w"> </span><span class="n">dtypeX</span><span class="p">,</span><span class="w"> </span><span class="n">dtypeY</span><span class="p">,</span><span class="w"> </span><span class="n">dtypeZ</span><span class="p">,</span><span class="w"> </span><span class="n">tileNum</span><span class="p">,</span><span class="w"> </span><span class="n">isSplit</span><span class="p">);</span>

<span class="w">    </span><span class="kt">size_t</span><span class="o">*</span><span class="w"> </span><span class="n">currentWorkspace</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetWorkspaceSizes</span><span class="p">(</span><span class="mi">1</span><span class="p">);</span>
<span class="w">    </span><span class="n">currentWorkspace</span><span class="p">[</span><span class="mi">0</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="w">    </span><span class="k">return</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">GRAPH_SUCCESS</span><span class="p">;</span>
<span class="p">}</span>
</code></pre></div><p>未切分分支只启动1个Block，由该Block处理完整Tensor；切分分支启动8个Block。这样，Host侧设置的<code>numBlocks</code>与核函数（Kernel）中基于<code>GetBlockNum()</code>计算的数据范围保持一致，避免小Shape分支的多个Block重复访问完整Tensor。</p><p><code>ASCENDC_TPL_SEL_PARAM</code>会按照模板参数的声明顺序，同时匹配传入的五个值。每个值都需要属于对应参数的取值集合，五个值组成的完整组合还必须被某个<code>ASCENDC_TPL_ARGS_SEL</code>覆盖。</p><p>例如，传入<code>(dtypeX, dtypeY, dtypeZ, tileNum, isSplit) = (C_DT_FLOAT16, C_DT_FLOAT16, C_DT_FLOAT16, 1, 0)</code>时，会命中模板参数头文件中的第一个<code>ASCENDC_TPL_ARGS_SEL</code>：三个dtype均为<code>C_DT_FLOAT16</code>，<code>tileNum</code>取值为<code>1</code>，<code>isSplit</code>取值为<code>0</code>。如果只将<code>dtypeY</code>改为<code>C_DT_FLOAT</code>，得到的混合dtype组合既不满足第一个组合的“全部为<code>C_DT_FLOAT16</code>”，也不满足第二个组合的“全部为<code>C_DT_FLOAT</code>”，因此无法命中任何组合。</p><h3 id="步骤三：核函数（Kernel）侧实现">步骤三：核函数（Kernel）侧实现<a class="header-anchor" href="#步骤三：核函数（Kernel）侧实现">​</a></h3><p>核函数（Kernel）实现文件需要包含模板参数定义头文件，并按照<code>ASCENDC_TPL_ARGS_DECL</code>中的类型和顺序声明核函数（Kernel）模板参数。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tiling_key_add_custom_template.h&quot;</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">D_T_X</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">D_T_Y</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">D_T_Z</span><span class="p">,</span>
<span class="w">          </span><span class="kt">int</span><span class="w"> </span><span class="n">TILE_NUM</span><span class="p">,</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">IS_SPLIT</span><span class="o">&gt;</span>
<span class="n">__global__</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom_template</span><span class="p">(</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">workspace</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">tiling</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// ... 省略其他核函数（Kernel）实现代码</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="p">(</span><span class="n">IS_SPLIT</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// 使用未切分实现</span>
<span class="w">    </span><span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// 使用切分实现</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>核函数（Kernel）可以通过<code>if constexpr</code>判断模板参数并选择对应实现，未命中的分支不会保留在当前核函数（Kernel）实例中。除模板声明和分支选择外，其他核函数（Kernel）实现代码按实际计算逻辑编写即可。</p><h3 id="编译加速">编译加速<a class="header-anchor" href="#编译加速">​</a></h3><p><code>--kernel-template-input</code>用于从<code>ASCENDC_TPL_SEL</code>声明的合法组合中筛选需要编译的核函数（Kernel）模板实例。选项中的键名取自核函数（Kernel）的模板参数，例如<code>D_T_X</code>、<code>TILE_NUM</code>，不是核函数（Kernel）入口的<code>GM_ADDR</code>参数名，也不是Host侧Tiling函数中的局部变量名。</p><p>以上文的模板组合为例，<code>ASCENDC_TPL_SEL</code>配置如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">ASCENDC_TPL_SEL</span><span class="p">(</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_ARGS_SEL</span><span class="p">(</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_DATATYPE_SEL</span><span class="p">(</span><span class="n">D_T_X</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT16</span><span class="p">),</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_DATATYPE_SEL</span><span class="p">(</span><span class="n">D_T_Y</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT16</span><span class="p">),</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_DATATYPE_SEL</span><span class="p">(</span><span class="n">D_T_Z</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT16</span><span class="p">),</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_UINT_SEL</span><span class="p">(</span><span class="n">TILE_NUM</span><span class="p">,</span><span class="w"> </span><span class="n">ASCENDC_TPL_UI_LIST</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">),</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_BOOL_SEL</span><span class="p">(</span><span class="n">IS_SPLIT</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">),</span>
<span class="w">    </span><span class="p">),</span>
<span class="w">    </span><span class="n">ASCENDC_TPL_ARGS_SEL</span><span class="p">(</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_DATATYPE_SEL</span><span class="p">(</span><span class="n">D_T_X</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT</span><span class="p">),</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_DATATYPE_SEL</span><span class="p">(</span><span class="n">D_T_Y</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT</span><span class="p">),</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_DATATYPE_SEL</span><span class="p">(</span><span class="n">D_T_Z</span><span class="p">,</span><span class="w"> </span><span class="n">C_DT_FLOAT</span><span class="p">),</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_UINT_SEL</span><span class="p">(</span><span class="n">TILE_NUM</span><span class="p">,</span><span class="w"> </span><span class="n">ASCENDC_TPL_UI_LIST</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">),</span>
<span class="w">        </span><span class="n">ASCENDC_TPL_BOOL_SEL</span><span class="p">(</span><span class="n">IS_SPLIT</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">),</span>
<span class="w">    </span><span class="p">),</span>
<span class="p">);</span>
</code></pre></div><p>第一个<code>ASCENDC_TPL_ARGS_SEL</code>固定三个dtype为<code>C_DT_FLOAT16</code>，并将<code>TILE_NUM</code>的两个取值与<code>IS_SPLIT</code>的两个取值组合，得到4个合法模板参数组合；第二个组合以<code>C_DT_FLOAT</code>得到另外4个。因此，不配置<code>--kernel-template-input</code>时，每个算子二进制编译任务会生成这8个核函数（Kernel）模板实例。</p><p><code>--kernel-template-input</code>不要求列出所有模板参数。未配置的参数会保留<code>ASCENDC_TPL_SEL</code>中声明的合法取值。例如，在<code>op_kernel/CMakeLists.txt</code>中增加以下配置，只保留<code>TILE_NUM=1</code>且<code>IS_SPLIT=0</code>的组合：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">ascendc_kernels</span><span class="w"> </span><span class="s">AddCustomTemplate</span>
<span class="w">    </span><span class="s">OPTIONS</span>
<span class="w">    </span><span class="s">--kernel-template-input=</span><span class="s2">&quot;TILE_NUM=1;IS_SPLIT=0&quot;</span>
<span class="p">)</span>
</code></pre></div><p>两个dtype组合均未被过滤，因此每个算子二进制编译任务会生成以下两个模板实例（示意）：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">add_custom_template</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="o">&gt;</span>
<span class="n">add_custom_template</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="o">&gt;</span>
</code></pre></div><p>同一模板参数需要保留多个值时，使用英文逗号分隔。例如，将<code>TILE_NUM</code>配置为<code>1,8</code>，并保持<code>IS_SPLIT=0</code>：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">ascendc_kernels</span><span class="w"> </span><span class="s">AddCustomTemplate</span>
<span class="w">    </span><span class="s">OPTIONS</span>
<span class="w">    </span><span class="s">--kernel-template-input=</span><span class="s2">&quot;TILE_NUM=1,8;IS_SPLIT=0&quot;</span>
<span class="p">)</span>
</code></pre></div><p>此时每个算子二进制编译任务会生成以下4个模板实例（示意）：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">add_custom_template</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="o">&gt;</span>
<span class="n">add_custom_template</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="o">&gt;</span>
<span class="n">add_custom_template</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="o">&gt;</span>
<span class="n">add_custom_template</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="o">&gt;</span>
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>不同模板参数之间使用英文分号分隔，配置中不能包含空格。数据类型参数填写核函数（Kernel）模板使用的C++类型名，例如<code>C_DT_FLOAT16</code>对应<code>half</code>，<code>C_DT_FLOAT</code>对应<code>float</code>。<code>--kernel-template-input</code>只能筛选<code>ASCENDC_TPL_SEL</code>已经声明的组合，不能生成未声明的新组合。配置时必须保留运行阶段可能选中的全部组合，否则对应场景将没有可用的核函数（Kernel）实例。</p></div><h2 id="如何选择">如何选择<a class="header-anchor" href="#如何选择">​</a></h2><p><strong>决策准则：</strong></p><ol><li>核函数（Kernel）代码需要在基础算子开发方式（&lt;&lt;&lt;&gt;&gt;&gt;）和aclnn工程化算子开发场景共用时，使用核函数（Kernel）模板方式。</li><li>分支较多、需要提升分支规则可读性时，使用核函数（Kernel）模板方式。</li><li>其他场景，按需选择TilingKey或核函数（Kernel）模板。</li></ol><h2 id="相关文档">相关文档<a class="header-anchor" href="#相关文档">​</a></h2><ul><li><a href="./operator_function_design.html">算子功能设计</a>：判断是否需要按dtype、shape或运行配置拆分核函数（Kernel）。</li><li><a href="./host_tiling_implementation.html">Host侧Tiling实现</a>：设置TilingData、TilingKey和核函数（Kernel）启动参数。</li><li><a href="./kernel_operator_implementation.html">核函数（Kernel）侧算子实现</a>：注册和解析不同TilingData结构体。</li><li><a href="../../../../../api/SIMD-API/basic_api/Kernel-Tiling/TILING_KEY_IS.html">TILING_KEY_IS</a>：核函数（Kernel）侧分支判断接口。</li><li><a href="../../../../../api/Utils-API/Tiling_template_programming/ASCENDC_TPL_SEL_PARAM.html">ASCENDC_TPL_SEL_PARAM</a>：Host侧模板参数选择接口。</li></ul></article></div>`,1)])])}const w=a(c,[["render",e]]);export{T as __pageData,w as default};
